<template><details v-if="row?.evidence?.length" class="model-row-evidence"><summary>{{ zh?'测试依据':'Test evidence' }} · {{ row.coverage }} {{ zh?'个能力源':'capability sources' }}<span v-if="row.configurationVaries"> · {{ zh?'配置不同':'Different configurations' }}</span></summary><ul><li v-for="e in row.evidence" :key="e.source"><a :href="e.url" target="_blank" rel="noopener noreferrer">{{ e.label }} · #{{ e.originalRank }}</a><span class="notranslate" translate="no">{{ e.model }}</span><small>{{ zh?'共同模型内':'Within common models' }} #{{ e.cohortRank }} · {{ e.version || (e.checkedAt?new Date(e.checkedAt).toLocaleDateString(locale):'') }}</small></li></ul></details></template>
